insert into public.termos_uso (versao, endereco, publicado_em) values (1, '/termos', '2026-10-01');
insert into public.modulos (numero, titulo, tema, descricao, publicado) values (1, 'Quem manda em quê?', 'Os Três Poderes', 'Quem faz o quê entre Executivo, Legislativo e Judiciário, e por que isso importa no seu dia a dia.', true);
insert into public.aulas (modulo_id, slug, numero, titulo, resumo, texto, publicado)
insert into public.questoes (aula_id, ordem, enunciado, explicacao) select id, 1, 'Quem administra o país e coloca as leis federais em prática?', 'O presidente comanda o Poder Executivo federal: administra o governo, os ministérios e executa as leis. Executar quer dizer colocar em prática.' from public.aulas where slug = 'tres-poderes';
insert into public.alternativas (questao_id, letra, texto, correta) select q.id, v.letra, v.texto, v.letra = 'A' from public.questoes q join public.aulas a on a.id = q.aula_id, (values ('A', 'O presidente da República'), ('B', 'O Senado'), ('C', 'O Supremo Tribunal Federal'), ('D', 'A Câmara dos Deputados')) as v(letra, texto) where a.slug = 'tres-poderes' and q.ordem = 1;
insert into public.questoes (aula_id, ordem, enunciado, explicacao) select id, 2, 'Qual Poder resolve conflitos aplicando as leis a casos concretos?', 'O Judiciário, formado por juízes e tribunais, decide disputas com base nas leis. O STF é o tribunal mais alto e guarda a Constituição.' from public.aulas where slug = 'tres-poderes';
insert into public.alternativas (questao_id, letra, texto, correta) select q.id, v.letra, v.texto, v.letra = 'C' from public.questoes q join public.aulas a on a.id = q.aula_id, (values ('A', 'O Executivo'), ('B', 'O Legislativo'), ('C', 'O Judiciário'), ('D', 'Nenhum deles')) as v(letra, texto) where a.slug = 'tres-poderes' and q.ordem = 2;
insert into public.questoes (aula_id, ordem, enunciado, explicacao) select id, 3, 'O Poder Legislativo federal é formado por:', 'Juntos, Câmara e Senado formam o Congresso Nacional. Por isso o sistema é chamado de bicameral: duas casas.' from public.aulas where slug = 'tres-poderes';
insert into public.alternativas (questao_id, letra, texto, correta) select q.id, v.letra, v.texto, v.letra = 'B' from public.questoes q join public.aulas a on a.id = q.aula_id, (values ('A', 'Câmara dos Deputados e STF'), ('B', 'Câmara dos Deputados e Senado Federal'), ('C', 'Presidência e ministérios'), ('D', 'Senado e governadores')) as v(letra, texto) where a.slug = 'tres-poderes' and q.ordem = 3;
insert into public.questoes (aula_id, ordem, enunciado, explicacao) select id, 4, 'Por que o poder é dividido em três?', 'A separação evita que uma só pessoa ou grupo concentre todo o poder. É o sistema de freios e contrapesos: cada Poder tem como frear o outro.' from public.aulas where slug = 'tres-poderes';
insert into public.alternativas (questao_id, letra, texto, correta) select q.id, v.letra, v.texto, v.letra = 'A' from public.questoes q join public.aulas a on a.id = q.aula_id, (values ('A', 'Para cada um fiscalizar e limitar os outros'), ('B', 'Para o governo gastar menos'), ('C', 'Porque cada estado escolhe um Poder'), ('D', 'Para as eleições acontecerem em datas diferentes')) as v(letra, texto) where a.slug = 'tres-poderes' and q.ordem = 4;
insert into public.aulas (modulo_id, slug, numero, titulo, resumo, texto, publicado)
insert into public.questoes (aula_id, ordem, enunciado, explicacao) select id, 1, 'Quem cria e vota as leis que valem para todo o Brasil?', 'O Congresso Nacional, formado pela Câmara dos Deputados e pelo Senado, cria e vota as leis federais. Prefeituras cuidam do município, e o STF julga se as leis respeitam a Constituição.' from public.aulas where slug = 'quem-faz-as-leis';
insert into public.alternativas (questao_id, letra, texto, correta) select q.id, v.letra, v.texto, v.letra = 'A' from public.questoes q join public.aulas a on a.id = q.aula_id, (values ('A', 'O Congresso Nacional'), ('B', 'A Prefeitura'), ('C', 'O Supremo Tribunal Federal'), ('D', 'Os governadores')) as v(letra, texto) where a.slug = 'quem-faz-as-leis' and q.ordem = 1;
insert into public.questoes (aula_id, ordem, enunciado, explicacao) select id, 2, 'Quantos deputados federais a Câmara tem?', 'São 513 deputados federais. Cada estado elege um número proporcional à sua população, com mínimo de 8 e máximo de 70.' from public.aulas where slug = 'quem-faz-as-leis';
insert into public.alternativas (questao_id, letra, texto, correta) select q.id, v.letra, v.texto, v.letra = 'C' from public.questoes q join public.aulas a on a.id = q.aula_id, (values ('A', '81'), ('B', '100'), ('C', '513'), ('D', '27')) as v(letra, texto) where a.slug = 'quem-faz-as-leis' and q.ordem = 2;
insert into public.questoes (aula_id, ordem, enunciado, explicacao) select id, 3, 'Quantos senadores cada estado elege?', 'Todo estado e o Distrito Federal elegem 3 senadores, não importa o tamanho. São 81 no total. O Senado representa os estados por igual.' from public.aulas where slug = 'quem-faz-as-leis';
insert into public.alternativas (questao_id, letra, texto, correta) select q.id, v.letra, v.texto, v.letra = 'B' from public.questoes q join public.aulas a on a.id = q.aula_id, (values ('A', 'Depende da população'), ('B', '3'), ('C', '1'), ('D', '8')) as v(letra, texto) where a.slug = 'quem-faz-as-leis' and q.ordem = 3;
insert into public.questoes (aula_id, ordem, enunciado, explicacao) select id, 4, 'O Congresso aprovou um projeto de lei. O que acontece em seguida?', 'Sancionar é concordar e transformar em lei. Vetar é recusar, no todo ou em parte. Se houver veto, o Congresso ainda pode derrubá-lo.' from public.aulas where slug = 'quem-faz-as-leis';
insert into public.alternativas (questao_id, letra, texto, correta) select q.id, v.letra, v.texto, v.letra = 'C' from public.questoes q join public.aulas a on a.id = q.aula_id, (values ('A', 'Ele vira lei automaticamente'), ('B', 'O STF precisa aprovar'), ('C', 'Vai para o presidente sancionar ou vetar'), ('D', 'Passa por um plebiscito')) as v(letra, texto) where a.slug = 'quem-faz-as-leis' and q.ordem = 4;
insert into public.questoes (aula_id, ordem, enunciado, explicacao) select id, 5, 'Quem faz as leis da sua cidade?', 'Na cidade, quem faz as leis são os vereadores, reunidos na Câmara Municipal. O prefeito comanda o Executivo municipal.' from public.aulas where slug = 'quem-faz-as-leis';
insert into public.alternativas (questao_id, letra, texto, correta) select q.id, v.letra, v.texto, v.letra = 'B' from public.questoes q join public.aulas a on a.id = q.aula_id, (values ('A', 'O Senado'), ('B', 'A Câmara Municipal'), ('C', 'O governador'), ('D', 'A Câmara dos Deputados')) as v(letra, texto) where a.slug = 'quem-faz-as-leis' and q.ordem = 5;
insert into public.aulas (modulo_id, slug, numero, titulo, resumo, texto, publicado)
insert into public.questoes (aula_id, ordem, enunciado, explicacao) select id, 1, 'Quem normalmente organiza os ônibus que circulam dentro de uma cidade?', 'O transporte coletivo municipal é responsabilidade da prefeitura. Linhas que ligam cidades diferentes costumam ficar com o estado.' from public.aulas where slug = 'municipio-estado-uniao';
insert into public.alternativas (questao_id, letra, texto, correta) select q.id, v.letra, v.texto, v.letra = 'C' from public.questoes q join public.aulas a on a.id = q.aula_id, (values ('A', 'A União'), ('B', 'O governo do estado'), ('C', 'A prefeitura'), ('D', 'O Senado')) as v(letra, texto) where a.slug = 'municipio-estado-uniao' and q.ordem = 1;
insert into public.questoes (aula_id, ordem, enunciado, explicacao) select id, 2, 'Quem vota as leis estaduais?', 'Cada estado tem uma Assembleia Legislativa, formada por deputados estaduais. É o Legislativo do estado.' from public.aulas where slug = 'municipio-estado-uniao';
insert into public.alternativas (questao_id, letra, texto, correta) select q.id, v.letra, v.texto, v.letra = 'A' from public.questoes q join public.aulas a on a.id = q.aula_id, (values ('A', 'A Assembleia Legislativa'), ('B', 'A Câmara Municipal'), ('C', 'O Congresso Nacional'), ('D', 'O Tribunal de Justiça')) as v(letra, texto) where a.slug = 'municipio-estado-uniao' and q.ordem = 2;
insert into public.questoes (aula_id, ordem, enunciado, explicacao) select id, 3, 'Quem comanda a Polícia Militar?', 'A Polícia Militar é estadual e fica subordinada ao governador. A Polícia Federal, essa sim, é da União.' from public.aulas where slug = 'municipio-estado-uniao';
insert into public.alternativas (questao_id, letra, texto, correta) select q.id, v.letra, v.texto, v.letra = 'B' from public.questoes q join public.aulas a on a.id = q.aula_id, (values ('A', 'O prefeito'), ('B', 'O governador do estado'), ('C', 'O presidente'), ('D', 'O Senado')) as v(letra, texto) where a.slug = 'municipio-estado-uniao' and q.ordem = 3;
insert into public.questoes (aula_id, ordem, enunciado, explicacao) select id, 4, 'Quem pode criar a moeda do país, o real?', 'Emitir moeda é competência da União, exercida pelo Banco Central. União é o nome do governo federal como ente da federação.' from public.aulas where slug = 'municipio-estado-uniao';
insert into public.alternativas (questao_id, letra, texto, correta) select q.id, v.letra, v.texto, v.letra = 'C' from public.questoes q join public.aulas a on a.id = q.aula_id, (values ('A', 'Cada estado'), ('B', 'Cada município'), ('C', 'A União'), ('D', 'Os bancos privados')) as v(letra, texto) where a.slug = 'municipio-estado-uniao' and q.ordem = 4;
insert into public.aulas (modulo_id, slug, numero, titulo, resumo, texto, publicado)
insert into public.questoes (aula_id, ordem, enunciado, explicacao) select id, 1, 'Quem pode apresentar um projeto de lei federal?', 'A Constituição permite várias origens. Iniciativa popular é quando os próprios cidadãos propõem um projeto, juntando assinaturas.' from public.aulas where slug = 'como-uma-lei-nasce';
insert into public.alternativas (questao_id, letra, texto, correta) select q.id, v.letra, v.texto, v.letra = 'C' from public.questoes q join public.aulas a on a.id = q.aula_id, (values ('A', 'Só deputados'), ('B', 'Só o presidente'), ('C', 'Parlamentares, o presidente e até cidadãos, por iniciativa popular'), ('D', 'Só os partidos políticos')) as v(letra, texto) where a.slug = 'como-uma-lei-nasce' and q.ordem = 1;
insert into public.questoes (aula_id, ordem, enunciado, explicacao) select id, 2, 'Um projeto de iniciativa popular federal precisa de assinaturas de, no mínimo:', 'São necessárias assinaturas de pelo menos 1% do eleitorado nacional, espalhadas por pelo menos cinco estados, com 0,3% dos eleitores de cada um.' from public.aulas where slug = 'como-uma-lei-nasce';
insert into public.alternativas (questao_id, letra, texto, correta) select q.id, v.letra, v.texto, v.letra = 'A' from public.questoes q join public.aulas a on a.id = q.aula_id, (values ('A', '1% do eleitorado nacional'), ('B', '10 mil pessoas'), ('C', 'Metade dos eleitores'), ('D', 'Um deputado')) as v(letra, texto) where a.slug = 'como-uma-lei-nasce' and q.ordem = 2;
insert into public.questoes (aula_id, ordem, enunciado, explicacao) select id, 3, 'Antes de ir à votação geral, um projeto costuma passar por:', 'Comissões são grupos menores de parlamentares que estudam o projeto por tema, como saúde ou educação, e dão um parecer antes do plenário.' from public.aulas where slug = 'como-uma-lei-nasce';
insert into public.alternativas (questao_id, letra, texto, correta) select q.id, v.letra, v.texto, v.letra = 'B' from public.questoes q join public.aulas a on a.id = q.aula_id, (values ('A', 'Uma eleição'), ('B', 'Comissões temáticas'), ('C', 'O STF'), ('D', 'As prefeituras')) as v(letra, texto) where a.slug = 'como-uma-lei-nasce' and q.ordem = 3;
insert into public.questoes (aula_id, ordem, enunciado, explicacao) select id, 4, 'O presidente vetou um projeto. O Congresso ainda pode:', 'Em sessão conjunta, deputados e senadores podem derrubar o veto com a maioria absoluta de cada casa. Aí o texto vira lei mesmo sem a sanção.' from public.aulas where slug = 'como-uma-lei-nasce';
insert into public.alternativas (questao_id, letra, texto, correta) select q.id, v.letra, v.texto, v.letra = 'C' from public.questoes q join public.aulas a on a.id = q.aula_id, (values ('A', 'Nada, o veto é definitivo'), ('B', 'Pedir ao STF que aprove'), ('C', 'Derrubar o veto em votação'), ('D', 'Refazer a eleição')) as v(letra, texto) where a.slug = 'como-uma-lei-nasce' and q.ordem = 4;
insert into public.leis (fonte, id_externo, rotulo, tema, ementa, resumo, apresentada_em, autoria, partido, coautores, publicada) values
  ('exemplo', 'exemplo-0418', 'PL 0418', 'Educação', 'Educação financeira no ensino médio', 'Inclui educação financeira como conteúdo obrigatório nas escolas públicas de ensino médio a partir do próximo ano letivo.', '2026-09-01', 'Dep. Bruno Modelo', 'PQZ', 0, true),
  ('exemplo', 'exemplo-0420', 'PL 0420', 'Transporte', 'Passe livre para estudantes', 'Garante transporte público gratuito para estudantes de escolas públicas em dias de aula, custeado por um fundo municipal.', '2026-09-02', 'Dep. Carla Teste', 'PWK', 0, true),
  ('exemplo', 'exemplo-0423', 'PL 0423', 'Saúde', 'Postos de saúde abertos até as 22h', 'Obriga as unidades básicas de saúde a funcionar em horário estendido nas cidades com mais de 100 mil habitantes.', '2026-09-03', 'Dep. Ana Exemplo', 'PEX', 0, true),
  ('exemplo', 'exemplo-0427', 'PL 0427', 'Meio ambiente', 'Fim das sacolas plásticas descartáveis', 'Proíbe a distribuição gratuita de sacolas plásticas descartáveis no comércio, com prazo de dois anos para adaptação.', '2026-09-04', 'Sen. Diego Hipótese', 'PJV', 0, true),
  ('exemplo', 'exemplo-0431', 'PL 0431', 'Segurança', 'Câmeras corporais em todos os policiais', 'Torna obrigatório o uso de câmeras corporais por policiais militares durante o patrulhamento, com gravação guardada por um ano.', '2026-09-05', 'Dep. Elisa Amostra', 'PXY', 0, true),
  ('exemplo', 'exemplo-0436', 'PL 0436', 'Trabalho', 'Semana de quatro dias no serviço público', 'Permite que órgãos públicos testem uma jornada de quatro dias por semana, sem redução de salário, por um período de dois anos.', '2026-09-06', 'Dep. Fábio Caso', 'PQZ', 0, true),
  ('exemplo', 'exemplo-0440', 'PL 0440', 'Cultura', 'Meia-entrada para cursinho popular', 'Estende o direito à meia-entrada em eventos culturais a estudantes matriculados em cursinhos populares pré-vestibular.', '2026-09-07', 'Sen. Gabi Ensaio', 'PEX', 0, true),
  ('exemplo', 'exemplo-0444', 'PL 0444', 'Saúde', 'Psicólogo em todas as escolas', 'Determina que toda escola pública com mais de 300 alunos tenha ao menos um psicólogo na equipe.', '2026-09-08', 'Dep. Hugo Rascunho', 'PWK', 0, true),
  ('exemplo', 'exemplo-0449', 'PL 0449', 'Transporte', 'Ciclovias obrigatórias em avenidas novas', 'Exige que toda avenida construída ou reformada com dinheiro federal inclua ciclovia separada dos carros.', '2026-09-09', 'Dep. Iara Protótipo', 'PJV', 0, true),
  ('exemplo', 'exemplo-0452', 'PL 0452', 'Educação', 'Wi-fi gratuito nas escolas públicas', 'Garante internet sem fio gratuita para alunos e professores em todas as escolas públicas, com velocidade mínima definida em regulamento.', '2026-09-10', 'Sen. João Simulado', 'PXY', 0, true),
  ('exemplo', 'exemplo-0455', 'PL 0455', 'Trabalho', 'Primeiro emprego com desconto de impostos', 'Reduz impostos para empresas que contratarem jovens de 16 a 24 anos sem experiência anterior com carteira assinada.', '2026-09-11', 'Dep. Karla Esboço', 'PJV', 0, true),
  ('exemplo', 'exemplo-0458', 'PL 0458', 'Meio ambiente', 'Coleta seletiva obrigatória em todas as cidades', 'Obriga todos os municípios a oferecer coleta seletiva de lixo reciclável em até cinco anos, com ajuda financeira da União.', '2026-09-12', 'Dep. Leo Exercício', 'PEX', 0, true),
  ('exemplo', 'exemplo-0461', 'PL 0461', 'Segurança', 'Iluminação pública perto das escolas', 'Determina que ruas num raio de 500 metros de escolas públicas tenham iluminação reforçada, custeada pelos municípios.', '2026-09-13', 'Sen. Marta Modelo', 'PXY', 0, true),
  ('exemplo', 'exemplo-0465', 'PL 0465', 'Cultura', 'Biblioteca aberta aos fins de semana', 'Obriga bibliotecas públicas municipais a abrir aos sábados e domingos em cidades com mais de 50 mil habitantes.', '2026-09-14', 'Dep. Nina Rascunho', 'PQZ', 0, true),
  ('exemplo', 'exemplo-0469', 'PL 0469', 'Saúde', 'Absorvente gratuito nas escolas', 'Garante a distribuição gratuita de absorventes higiênicos em todas as escolas públicas de ensino fundamental e médio.', '2026-09-15', 'Dep. Otávio Caso', 'PWK', 0, true);
